export function fieldNotesView({activity,icon,logo,dateText,distance,duration,paceText,summaryPace,escape,routePanel,stats,observationPanel,analysisPanel,blocksPanel,sourceNote,inlineCheckin,miniRoute,reduced,systemReduced}) {
  const gps=activity.records.some(r=>r.lat!==null&&r.lon!==null);
  const canReplay=gps&&activity.records.length>1&&activity.records.at(-1).t>0;
  return `<header class="fn-header"><a href="/" class="fn-brand" aria-label="My Fitness Analyser home">${logo}<span>My Fitness Analyser<small>Your training, collected.</small></span></a><nav aria-label="Activity navigation"><button data-action="activities">Activities</button><a href="#session-details">In detail</a><button data-action="checkin">Your notes</button></nav><div class="fn-header-actions"><button class="fn-motion" data-action="motion" aria-pressed="${!reduced}" ${systemReduced?'disabled':''} aria-label="${systemReduced?'Motion follows system reduced-motion setting':'Toggle visual motion'}"><i aria-hidden="true"></i><span>${systemReduced?'System motion off':reduced?'Motion off':'Motion on'}</span></button><button class="icon-button" data-action="source" aria-label="Activity sources">${icon('layers')}</button><button class="fn-avatar" data-action="review" aria-label="Preview settings">S</button></div><div class="fn-reading-progress" aria-hidden="true"></div></header>
  <main id="main" class="fn-main">
    <section class="fn-hero" aria-labelledby="activity-title" id="overview">
      <div class="fn-aura" aria-hidden="true"></div>
      <div class="fn-intro"><p class="fn-date">${escape(activity.sport)} <span></span> ${dateText(activity.date)}${activity.time?`<span class="fn-time">${escape(activity.time)}</span>`:''}</p><h1 id="activity-title">${escape(activity.title)}</h1><div class="fn-source"><span class="fn-source-dot"></span>${escape(activity.source)}${activity.synthetic?'<span class="synthetic-label">Synthetic data</span>':''}<button data-action="source" class="text-button" aria-label="View activity provenance">${icon('info')}</button></div></div>
      <div class="fn-art"><div class="fn-glint" aria-hidden="true"></div><div class="fn-orbit" aria-hidden="true"></div>${routePanel()}<div class="fn-replay-controls"><button class="fn-replay" data-action="route-replay" aria-pressed="false" ${!canReplay||reduced?'disabled':''}>${icon('play')}<span>${!canReplay?'Replay unavailable':reduced?'Replay · motion off':'Replay route'}</span></button><span>${canReplay?'12-second visual preview':'Summary preserved'}</span></div></div>
      <div class="fn-primary"><div class="fn-distance"><span>${distance(activity.distance)}</span><small>km</small></div><p>Distance covered</p></div>
      <div class="fn-hero-footer">${stats()}<a class="fn-scroll-cue" href="#session-finding"><span>Explore this session</span>${icon('chevrondown')}</a></div>
    </section>
    <section class="fn-finding fn-chapter" id="session-finding" aria-label="Session observation"><div class="fn-chapter-label"><span class="fn-hairline"></span><span>The session, understood</span></div>${observationPanel()}<div class="fn-finding-foot"><p>One session. A closer look.</p><a href="#session-details" class="fn-round-link" aria-label="Explore the session details">${icon('chevrondown')}</a></div></section>
    <section class="fn-details fn-chapter" id="session-details" aria-label="Recorded session details"><aside class="fn-atlas"><div class="fn-chapter-label"><span class="fn-hairline"></span><span>Follow the detail</span></div><h2>Every part<br>has its place.</h2><div class="fn-mini-map">${gps?`<div class="route-svg">${miniRoute}</div>`:`<div class="fn-missing-route">${icon('route')}<p>No GPS in this record.<br>Your session facts are preserved.</p></div>`}</div><div class="fn-atlas-caption"><span class="route-selection">Full activity</span><span>${gps?'Recorded GPS outline':'Source summary'}</span></div><p class="fn-atlas-note">${gps?'Choose a time block to connect the route and chart.':'Available summaries and displayed splits stay intact.'}</p></aside><div class="fn-detail-content">${analysisPanel()}${blocksPanel()}</div></section>
    ${sourceNote()}
    <section class="fn-notes-section fn-chapter"><div class="fn-notes-aside"><div class="fn-chapter-label"><span class="fn-hairline"></span><span>Your side of the story</span></div><h2>The numbers.<br>The feeling.<br>The whole picture.</h2><p>The record holds the numbers.<br>You add what it felt like.</p><span class="fn-note-mark" aria-hidden="true">${logo}</span></div>${inlineCheckin()}</section>
    <footer class="fn-recap fn-chapter"><div><span class="fn-chapter-label">My Fitness Analyser</span><h2>A session,<br>made yours.</h2></div><div class="fn-recap-record"><p>${escape(activity.title)}</p><strong>${distance(activity.distance)}<small> km</small></strong><span>${duration(activity.timer??activity.running??activity.moving)} <i></i> ${paceText(summaryPace())} /km</span><button class="text-button" data-action="source">View the source ${icon('plus')}</button></div><div class="fn-recap-bottom"><span>${activity.synthetic?'Synthetic design sample':'Your imported activity'} · Check-ins stay in this browser preview</span><a href="#overview">Back to the session ${icon('arrow')}</a></div></footer>
  </main>`;
}
